#include <zephyr/kernel.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/rtio/rtio_work.h>
#include <zephyr/sys/atomic.h>
#include <zephyr/sys/slist.h>

#ifdef CONFIG_RTIO_WORK_QUEUE_STACK_SIZE
K_THREAD_STACK_DEFINE(rtio_work_q_stack, CONFIG_RTIO_WORK_QUEUE_STACK_SIZE);
struct k_work_q rtio_work_q;
#endif

void rtio_work_submit(struct rtio_work *work)
{
#ifdef CONFIG_RTIO_WORK_QUEUE_STACK_SIZE
	k_work_submit_to_queue(&rtio_work_q, &work->work);
#else
	k_work_submit(&work->work);
#endif
}

void rtio_work_req_submit(struct rtio_work_req *req)
{
	if (req == NULL) {
		/* A NULL request should be rejected, not processed. */
		return;
	}

	struct rtio_work *work = req->work;
	struct rtio *r = req->r;

	k_work_init(&work->work, work->handler);
	work->req = req;

	rtio_work_submit(work);
}

void rtio_work_req_init(struct rtio_work_req *req, struct rtio *r,
			struct rtio_work *work)
{
	req->r = r;
	req->work = work;
}

#ifdef CONFIG_RTIO_WORK_QUEUE_STACK_SIZE
static void rtio_work_q_init(void)
{
	k_work_q_start(&rtio_work_q, rtio_work_q_stack,
		       K_THREAD_STACK_SIZEOF(rtio_work_q_stack),
		       CONFIG_RTIO_WORK_QUEUE_PRIORITY, NULL);
}

SYS_INIT(rtio_work_q_init, APPLICATION, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);
#endif
